INSERT INTO `knowledge_chapter` (`id`, `course_id`, `parent_id`, `chapter_code`, `title`, `level`, `sort_order`, `description`, `summary`) VALUES
(158, 1, 0, '7', '第 7 章 面向对象程序设计（下）', 1, 7, '本章围绕继承与多态展开，依次介绍如何扩展一个类（extends）、protected 数据和方法、super 的两种用法、方法重写、final 关键字、密封类、Object 类及其 toString() 与 equals() 方法、多态、动态绑定、对象转换（向上转换与向下转换）、抽象类与抽象方法及其 Calendar、Number 示例、接口的声明与实现（父接口与子接口、默认方法、静态与私有方法、默认方法冲突、密封接口、注解与注解接口）、Comparable 接口示例、抽象类与接口的比较与选择，最后介绍面向对象程序设计的五个基本原则（SOLID）。', '随着软件越来越复杂、软件规模越来越庞大，软件重用（Software Reuse）越来越受到重视。“不要重复发明轮子（Stop trying to reinvent the wheel）”，可能是每个程序员入行被告知的一条准则。使用已经造好的轮子，而不是从零开始开发，就是体现了软件重用的思想。软件重用既能降低软件开发的工作量和成本，也能提高软件的可靠性。\n继承机制就是面向对象技术提供的一种软件重用方式，即在定义一个新的类时，可以考虑把一个或多个已有类的功能全部包含进来，然后，增加新功能的代码或者重新定义已有功能的代码。继承机制不需要修改已有软件代码，是一种基于源代码的重用机制。\n在一个继承体系中，不同层次的类具有相似功能的不同方法需要使用同一名称来实现，从而可以使用相同的调用方式来调用这些具有不同功能的同名方法，这就需要引入多态性的概念，解决类的功能和行为在继承体系中的再抽象问题。\n本章主要围绕继承和多态展开介绍，介绍了如何扩展一个类、protected 修饰符、super 关键字、方法重写、final 关键字、密封类、Object 类及其常用方法、多态和动态绑定、对象转换、抽象类和接口。最后，简要介绍了面向对象程序设计原则。'),
(159, 1, 158, '7.1', '继承', 2, 1, NULL, NULL),
(160, 1, 159, '7.1.1', '父类与子类', 3, 1, NULL, NULL),
(161, 1, 159, '7.1.2', 'protected 数据和方法', 3, 2, NULL, NULL),
(162, 1, 158, '7.2', 'super', 2, 2, '关键字 super 主要用在继承机制中，它指向 super 所在类的直接父类，主要有两种使用方式：一是在子类构造方法中调用父类的构造方法；二是调用父类的普通方法。', NULL),
(163, 1, 162, '7.2.1', '调用父类构造方法', 3, 1, NULL, NULL),
(164, 1, 162, '7.2.2', '调用父类普通方法', 3, 2, NULL, NULL),
(165, 1, 158, '7.3', '方法重写', 2, 3, '子类不仅可以继承父类的方法，还可以根据自己的需要重新定义从父类继承而来的方法。子类重新定义从父类继承而来的方法，称为方法重写或方法覆盖（method overriding）。图 7-6 所示的代码段 1 或代码段 2 就是方法重写的例子。方法 toString()在类 Account 中有定义，然后在子类 DebitCardAccount 和子类 CreditCardAccount 中又被重新定义。在图 7-6 中，还可以看到@Override 符号，这个符号被称为重写标注。在子类的一个实例方法前放置一个重写标注，这表示被标注的方法必须重写父类的某个方法。如果被标注方法没有重写父类的某个方法，那么编译器就会报告一个错误。这样可以避免一些拼写错误。例如，子类 DebitCardAccount 在重写方法 toString()时使用了重写标注，而 toString 被错误地输入为 toSting，不小心漏掉一个字母，那么编译器将会报告一个错误。如果没有使用重写标注，那么编译器不会报告错误。', NULL),
(166, 1, 158, '7.4', 'final', 2, 4, '关键字 final 既可用于定义一个常量，也可以在继承机制中，用于防止继承和方法重写。', NULL),
(167, 1, 158, '7.5', '密封类(Sealed Classes)', 2, 5, 'Java 17 的新特性之一是正式引入了密封类（Sealed classes）。密封类概念在其他语言中，早就存在了。例如，C#语言中的密封类表示该类是最终类（不可被继承）。又比如，在 Kotlin 语言(一个基于 JVM 的新编程语言)，密封类要求其子类只能在当前源文件中定义。', NULL),
(168, 1, 158, '7.6', 'Object 类', 2, 6, '在 Java 语言中，类 Object（java.lang.Object）是所有其他类的父类（或祖先类）。如果一个类在定义时没有明确指定父类，那么该类默认地继承类 Object，类 Object 是其默认父类。例如，图 7-7 所示的两段代码是一样的。因此，凡是没有明确指定父类的类，都是类 Object 的隐含子类。（图 7-7　默认继承 Object：左侧代码 public class ClsA{…} 与右侧代码 public class ClsA extends Object{…} 之间标注“等价”）', NULL),
(169, 1, 168, '7.6.1', 'toString( )', 3, 1, NULL, NULL),
(170, 1, 168, '7.6.2', 'equals( )', 3, 2, NULL, NULL),
(171, 1, 158, '7.7', '多态', 2, 7, '在 Java 语言中，继承的出现使得父类引用变量可以是多态的。具体来讲，一个父类引用变量既可以引用一个父类类型的对象，又可以引用其任何一个子类类型的对象。因此，父类引用变量是具有多种形态的。', NULL),
(172, 1, 158, '7.8', '动态绑定', 2, 8, '动态绑定（dynamic binding）是实现多态性的关键技术，是指在运行期间判断所引用对象的实际类型，根据其实际类型调用相应的方法。例如，在 7.6 节的示例中，程序清单 7-12 中的方法 display 根据父类引用变量 s 所引用的实际类型，调用相应的方法。', NULL),
(173, 1, 158, '7.9', '对象转换', 2, 9, '对象转换是指一类对象的引用可以类型转换为另一类对象的引用。', NULL),
(174, 1, 158, '7.10', '抽象类', 2, 10, '在现实世界中，一些高层概念是抽象的和通用的，这些概念是没有对应的具体实例的。例如，动物、植物、交通工具、水果、蔬菜等概念都是较抽象的高层概念，没有具体的实例。这样的概念用面向对象方法建模表示时，可以使用抽象类（abstract class）来表示。抽象类是没有具体实例的类，在 Java 语言中，使用关键字 abstract 修饰抽象类的定义。例如，定义一个公有抽象类的一般形式如下：', NULL),
(175, 1, 158, '7.11', '抽象类示例', 2, 11, NULL, NULL),
(176, 1, 175, '7.11.1', '抽象类 Calendar 和子类 GregorianCalendar', 3, 1, NULL, NULL),
(177, 1, 175, '7.11.2', '抽象类 Number 及其子类', 3, 2, NULL, NULL),
(178, 1, 158, '7.12', '接口', 2, 12, '在 Java 语言中，接口（interface）可以用来提供一些相关类或不相关类具有的共同行为，但不提供这些行为的具体实现。接口是一种与类相似的构造，定义了一种新的数据类型，可以通过接口的名称声明引用变量。', NULL),
(179, 1, 178, '7.12.1', '普通接口声明', 3, 1, NULL, NULL),
(180, 1, 178, '7.12.2', '接口实现', 3, 2, NULL, NULL),
(181, 1, 178, '7.12.3', '父接口、子接口', 3, 3, NULL, NULL),
(182, 1, 178, '7.12.4', '默认方法、静态和私有方法', 3, 4, NULL, NULL),
(183, 1, 178, '7.12.5', '默认方法冲突', 3, 5, NULL, NULL),
(184, 1, 178, '7.12.6', '密封接口(Sealed interfaces)', 3, 6, NULL, NULL),
(185, 1, 178, '7.12.7', '注解与注解接口（Annotation Interface）', 3, 7, NULL, NULL),
(186, 1, 158, '7.13', '接口示例 1：Comparable 接口', 2, 13, 'Java 语言提供了 java.lang.Comparable 接口，用于两个相同类型对象之间的比较。例如，接口 Comparable 可用于比较两个平面封闭形状对象（比较的依据可以是面积或周长），更具体地讲，可以比较两个圆对象、两个矩形对象、或两个三角形对象。又如，接口 Comparable 还可以用于比较两个日期对象、两个学生对象、两个教师对象等。这些数据类型都具有一个特征就是可比较的（Comparable）。于是，接口 Comparable 可用于组织这些可比较的对象。', NULL),
(187, 1, 158, '7.14', '抽象类与接口', 2, 14, '抽象类与接口的使用相似，不能使用 new 关键字创建自身实例，然而，可以声明抽象类类型或接口类型的引用变量，这些引用变量可以用来指向它们具体子类的实例。', NULL),
(188, 1, 158, '7.15', '面向对象程序设计原则', 2, 15, '在面向对象方法中，SOLID（单一功能、开闭原则、里氏替换、接口隔离以及依赖倒置）是首字母缩略字，指代面向对象程序设计的五个基本原则。当这些原则被一起应用时，它们使得程序员开发一个容易进行维护和扩展的系统成为可能。程序员遵循 SOLID 原则对软件源代码进行重构，可以提升源代码的易读性以及软件的可维护性和可扩展性。', NULL),
(189, 1, 158, '7.16', '课程思政', 2, 16, NULL, NULL),
(190, 1, 189, '7.16.1', '继承先辈优秀遗产，发扬创新', 3, 1, NULL, NULL),
(191, 1, 189, '7.16.2', '树立坚定不移推进高水平对外开放的意识', 3, 2, NULL, NULL);
