INSERT INTO `knowledge_concept` (`id`, `chapter_id`, `name`, `definition`, `difficulty`, `page`, `page_order`) VALUES
(375, 159, '软件重用', '使用已经造好的轮子，而不是从零开始开发，就是体现了软件重用的思想。软件重用既能降低软件开发的工作量和成本，也能提高软件的可靠性。', 1, 290, 1),
(376, 159, '继承机制', '继承机制就是面向对象技术提供的一种软件重用方式，即在定义一个新的类时，可以考虑把一个或多个已有类的功能全部包含进来，然后，增加新功能的代码或者重新定义已有功能的代码。继承机制不需要修改已有软件代码，是一种基于源代码的重用机制。', 1, 290, 2),
(377, 160, '关键字 extends', '关键字 extends 用在子类名之后，指定父类名，父类只允许有一个。', 1, 291, 1),
(378, 160, '单继承', 'Java 语言是一种单继承语言，即子类继承父类使用关键字 extends 时，extends 之后只能有一个父类名。', 1, 298, 1),
(379, 160, '子类不是父类的子集', '子类继承父类的内容，还可以新增内容和重写继承的内容。因此，子类不是父类的子集。', 1, 298, 2),
(380, 160, '构造方法不是成员', '据 Java 语言官方文档，子类继承了父类中所有可被访问的成员（数据域和方法），但是构造方法不是成员，父类构造方法不被能子类继承。然而，父类构造方法可以被子类调用，用于完成子类的初始化工作。', 1, 298, 3),
(381, 160, '父类私有成员的继承', '从内存分配上讲，子类确实继承父类的私有成员。因为在实例化一个子类对象时，系统先为父类中定义的数据域（包括私有成员）分配内存，再为子类中定义的数据域分配内存，所有这些数据域都是属于这个新创建的对象，只不过子类对象不能直接访问其父类的私有成员。', 1, 298, 4),
(382, 160, '“是一种（is-a）”关系与继承建模', '不是所有“是一种（is-a）”关系都应该用继承来建模。例如，正方形是一种矩形，但是不应该定义一个正方形类继承自矩形类。', 1, 298, 5),
(383, 161, '受保护的成员', '父类中被 protected 修饰的成员被称为受保护的成员。无论父类与其子类是否在同一包中，父类的受保护成员可以在它的子类中被访问。', 1, 298, 1),
(384, 161, '可见性修饰符', '可见性修饰符 public、protected、private，指定了类和类的成员的可见性（或可访问性）。', 1, 298, 2),
(385, 161, '包私有类的成员可访问性', '当这些可见性修饰符修饰一个非 public 类（包私有类）的成员时，这些成员的可访问性就受限于一个包的范围。', 1, 299, 1),
(386, 161, 'protected 与信息隐藏', '在继承机制下，为了实现更好的信息隐藏，最好是在父类中使用可见性修饰符 protected。在父类中使用 protected 声明的成员，被继承后在子类中就像公有成员一样，可由子类方法直接访问。', 1, 300, 1),
(387, 162, '关键字 super', '关键字 super 主要用在继承机制中，它指向 super 所在类的直接父类，主要有两种使用方式：一是在子类构造方法中调用父类的构造方法；二是调用父类的普通方法。', 1, 300, 1),
(388, 163, '显式调用父类构造方法', '而且，super( )或 super(实际参数列表)必须出现在子类构造方法的第一行。这是显式调用父类构造方法的唯一形式。', 1, 300, 1),
(389, 163, '隐式调用父类构造方法', '如果子类构造方法没有显式调用父类构造方法，那么编译器将自动放置 super( )作为构造方法的第一条语句。', 1, 300, 2),
(390, 163, '子类构造方法的执行顺序', '子类构造方法在执行时，会沿着继承链从根类 Object 出发向下依次调用所有父类的构造方法，最后执行子类自身的初始化语句。', 1, 301, 1),
(391, 164, '调用父类普通方法', '子类可以使用关键字 super 调用父类的普通方法，其语法形式如下：', 1, 302, 1),
(392, 165, '方法重写（方法覆盖）', '子类不仅可以继承父类的方法，还可以根据自己的需要重新定义从父类继承而来的方法。子类重新定义从父类继承而来的方法，称为方法重写或方法覆盖（method overriding）。', 1, 302, 1),
(393, 165, '重写标注', '在子类的一个实例方法前放置一个重写标注，这表示被标注的方法必须重写父类的某个方法。如果被标注方法没有重写父类的某个方法，那么编译器就会报告一个错误。这样可以避免一些拼写错误。', 1, 302, 2),
(394, 165, '重写的方法签名与返回类型', '子类中重写的方法必须和父类中被重写的方法具有相同的方法签名，具有一样或兼容的返回类型。兼容的含义是指子类中重写方法的返回类型可以是父类中被重写方法的返回类型的子类型。', 1, 302, 3),
(395, 165, '父类私有方法不能被子类重写', '仅当父类的一个实例方法可以被子类访问时，该实例方法才能被重写。因此，父类的私有方法不能被子类重写。这是因为父类的私有方法只在父类内部可访问。', 1, 302, 4),
(396, 165, '重写不能降低方法的可访问性', '重写方法时，不能降低方法的可访问性。具体来说，父类中被重写方法的可见性修饰符是 public，那么子类中重写方法的可见性修饰符必须是 public。', 1, 303, 1),
(397, 165, '静态方法隐藏', '静态方法能够被继承，但不能被重写。如果子类重新定义父类中的静态方法，那么父类的静态方法会被隐藏。如果需要调用父类被隐藏的静态方法，可以使用语法“父类名.静态方法名(实际参数列表)”调用。', 1, 303, 2),
(398, 165, '方法重写与方法重载的区别', '方法重写发生在具有继承关系的不同类中；方法重载既可以发生在同一个类中，也可以发生在不同类中。方法重写要求方法签名相同；而方法重载要求方法名相同而方法签名不同。', 1, 303, 3),
(399, 166, '关键字 final', '关键字 final 既可用于定义一个常量，也可以在继承机制中，用于防止继承和方法重写。', 1, 303, 1),
(400, 166, '最终类', '如果一个类 ClsA 不能被其他类继承时，那么可以使用关键字 final 修饰类 ClsA。此时，类 ClsA 就是一个最终类，不允许被继承', 1, 303, 2),
(401, 166, '最终方法', '如果一个方法是最终的（该方法被关键字 final 修饰），那么这个方法就不能被子类重写。', 1, 303, 3),
(402, 167, '密封类', '如果一个类被声明为密封类，那么该类的所有直接子类都是已知的，并且不能再有其他直接子类。这种方式对一个类的所有直接子类进行显式和详尽的控制。', 1, 303, 1),
(403, 167, '引入密封类的原因', '为什么引入密封类呢？这是为了对继承能力进行限制。在面向对象程序设计语言中，继承可以用来实现代码复用。然而，有时候我们不希望继承被滥用，不希望一个类被继承后去做一些不可预知的扩展，或者不希望一个类任意被扩展', 1, 303, 2),
(404, 167, 'sealed 与 permits', 'Java 语言使用 sealed 关键字声明密封类，使用 permit 关键声明哪个类可以是直接子类。而继承密封类的子类必须被声明为 sealed 或 non-sealed 或 final。', 1, 304, 1),
(405, 167, 'non-sealed（非密封的）', '允许的子类可以声明为非密封的（non-sealed），这样允许的子类可以被任意的扩展（未知的子类也可以被扩展）。密封类不能阻止其允许的子类声明为 non-sealed。', 1, 304, 2),
(406, 167, '允许子类的三个修饰符互斥', '一个允许的子类只能使用三个修饰符（final、sealed、non-sealed）中的一个来进行修饰，不能同时使用多个进行修饰。', 1, 305, 1),
(407, 168, 'Object 类', '在 Java 语言中，类 Object（java.lang.Object）是所有其他类的父类（或祖先类）。如果一个类在定义时没有明确指定父类，那么该类默认地继承类 Object，类 Object 是其默认父类。', 1, 305, 1),
(408, 168, 'Object 的无参构造方法', '类 Object 提供了一个无参构造方法：public Object()。类 Object 的子类的构造方法会默认调用类 Object 的无参构造方法。', 1, 305, 2),
(409, 169, 'toString( ) 方法', '其功能是以字符串形式显示一个对象的信息。默认情况下，一个对象的信息由三个部分组成：该对象所属的类名、at 符号(@)、十六进制形式表示的该对象的内存地址。', 1, 306, 1),
(410, 169, 'toString( ) 的自动调用', '当一个字符串和一个对象进行连接时，这个对象会自动调用自己的 toString()方法，得到自己的字符串表示形式。', 1, 307, 1),
(411, 170, 'equals( ) 方法', '其功能是测试两个对象是否相等。调用该方法的一般形式是：', 1, 307, 1),
(412, 170, 'equals 方法的默认实现', '这个默认实现是使用==（相等比较运算符）判断两个引用变量是否指向同一个对象。因此，默认实现的功能与==运算符的功能是一样的。', 1, 307, 2),
(413, 170, 'equals( ) 的内容比较', '方法 equals()在 Java API 的许多类中被重写，其功能不再是比较两个引用变量是否指向同一个对象，而是比较两个对象的内容是否相同。例如，java.lang.String 对方法 equals()进行了重写，用于比较两个字符串对象的内容是否相等。', 1, 307, 3),
(414, 170, '字符串对象的引用比较与内容比较', '由于==运算符比较的是对象引用，所以，s1 == s2、s1 == s3 为 false，s2 == s3 为 true。然而，方法 equals()比较的是字符串内容，因此，s1.equals(s2)、s1.equals(s3)、s2.equals(s3)结果均为 true。', 1, 307, 4),
(415, 171, '多态', '在 Java 语言中，继承的出现使得父类引用变量可以是多态的。具体来讲，一个父类引用变量既可以引用一个父类类型的对象，又可以引用其任何一个子类类型的对象。因此，父类引用变量是具有多种形态的。', 1, 308, 1),
(416, 171, '多态性存在的三个必要条件', '多态性存在的三个必要条件是：第一要有继承；第二要有方法重写；第三父类引用变量指向其子类对象。', 1, 308, 2),
(417, 172, '动态绑定', '动态绑定（dynamic binding）是实现多态性的关键技术，是指在运行期间判断所引用对象的实际类型，根据其实际类型调用相应的方法。', 1, 312, 1),
(418, 172, '声明类型与实际类型', '一个变量在定义时，首先要声明其数据类型，这个数据类型就是变量的声明类型。例如，Shape s; 就声明了一个 Shape 类型的变量 s。一个变量的实际类型是该变量引用的对象的实际类型。', 1, 312, 2),
(419, 172, '方法匹配', '在编译阶段，编译器根据对象 obj 的声明类型匹配方法的签名，完成编译，这个过程也被称为方法匹配。在运行阶段，JVM 会根据对象 obj 的实际类型绑定具体的方法实现。', 1, 312, 3),
(420, 172, '沿继承链寻找最近的方法实现', '那么 JVM 在进行方法绑定时，会从对象 obj 的实际类型 Ci 开始，沿着继承链向 Object 方向寻找一个最近的方法实现。', 1, 312, 4),
(421, 173, '对象转换', '对象转换是指一类对象的引用可以类型转换为另一类对象的引用。', 1, 313, 1),
(422, 173, '向上转换（upcasting）', '从语义上来看，子类对象（Circle 类对象）是父类（Shape 类）的一个实例，换句话说，一个圆（Circle）是一个形状（Shape）。因此，总是可以把一个子类的对象转换成一个父类引用变量，这称为向上转换（upcasting）。', 1, 313, 2),
(423, 171, '父类引用变量作为方法的形式参数', '为什么在定义一些方法时用父类引用变量作为形式参数，不用具体的子类引用变量作为形式参数呢？这主要是为了增强一个方法的通用性，也是实现多态性的条件之一。', 1, 314, 1),
(424, 173, '向下转换（downcasting）', '这种显式转换，把一个父类引用变量转换成它的子类引用变量，被称为向下转换（downcasting）。向下转换必须采用显式转换的形式，而且必须确保要转换的父类引用变量所指向的实例是其相应子类的一个实例。', 1, 314, 1),
(425, 173, 'ClassCastException', '如果父类引用变量所指向的对象不是相应子类的一个实例，那么程序在运行时会抛出一个运行时异常 ClassCastException。', 1, 314, 2),
(426, 173, 'instanceof 运算符', 'instanceof 运算符是二元运算符，左边的操作元是一个对象，右边是一个类。当左边的对象是右边的类或子类创建的对象时，instanceof 运算的结果是 true，否则是 false。', 1, 314, 3),
(427, 173, 'instanceof 运算优先级', 'instanceof 运算优先级介于比较运算符之间，低于不等比较运算符(<, <=, >, >=)，高于相等与否比较运算符（==，!=）。', 1, 314, 4),
(428, 174, '抽象类', '抽象类是没有具体实例的类，在 Java 语言中，使用关键字 abstract 修饰抽象类的定义。', 1, 314, 1),
(429, 174, '抽象方法', '抽象方法是没有具体实现的方法，即无需定义方法体。定义抽象方法时，需要在方法头的返回值类型之前使用关键字 abstract 进行修饰。', 1, 314, 2),
(430, 174, '抽象类不能使用 new 创建实例', '抽象类不能使用 new 关键字创建自己的实例，例如，抽象类 ShapeObj 类不能创建自己的实例。', 1, 318, 1),
(431, 174, '抽象类的构造方法', '通常，抽象类的构造方法应被设计成 protected 权限，仅被其子类调用。具体地，当创建一个具体子类的实例时，抽象父类的构造方法仅可被该具体子类的构造方法调用，用于初始化抽象父类中定义的数据域。', 1, 318, 2),
(432, 174, '通过抽象父类引用变量调用抽象方法', '通过抽象父类引用变量调用抽象方法，这种做法是正确的，不会产生编译错误。', 1, 318, 3),
(433, 174, '抽象方法是非静态的', '抽象方法是非静态的。静态方法不能被定义为抽象的。这是因为抽象方法是没有实现的，而静态方法在一个类加载到 JVM 时，就可以被调用和使用，静态方法是必须要有方法实现的。', 1, 319, 1),
(434, 176, 'Calendar 类', 'java.util.Calendar 是一个抽象类，可用于表示详细的日历信息，例如，年、月、日、时、分、秒等。Calendar 类的具体子类可以实现特定的日历系统。', 1, 319, 1),
(435, 176, '公历类 GregorianCalendar', '目前，Java 语言内建支持公历日历系统的实现，提供了公历类 java.util.GreGorianCalendar。', 1, 319, 2),
(436, 176, '日历域 MONTH', '日历域 MONTH 是基于 0，即，0 表示一月，1 表示二月，依次类推', 1, 320, 1),
(437, 177, 'Number 抽象类', 'Java 语言提供了 java.lang.Number 抽象类，它是数值包装类（Byte、Short、Integer、Long、Float、Double）、BigInteger、BigDecimal 的抽象父类。', 1, 324, 1),
(438, 177, 'Number 的共有方法', '上述 6 个共有方法，除了 byteValue()、shortValue()方法外，其他 4 个方法都是抽象方法。这 4 个抽象方法需要在各个子类中进行实现。', 1, 324, 2),
(439, 178, '接口', '在 Java 语言中，接口（interface）可以用来提供一些相关类或不相关类具有的共同行为，但不提供这些行为的具体实现。接口是一种与类相似的构造，定义了一种新的数据类型，可以通过接口的名称声明引用变量。', 1, 325, 1),
(440, 178, '两种类型的接口声明', 'Java 语言有两种类型的接口声明：普通接口声明(normal interface declarations)、注解接口声明(annotation interface declarations)。', 1, 325, 2),
(441, 179, '接口名的命名惯例', '接口名是一个合法标识符，通常命名为形容词，表示一种该接口提供一种能力，例如，Comparable（可比较的）、Serializable（可串行化的）、Computable（可计算的）。', 1, 326, 1),
(442, 179, '接口中的常量', '接口体中定义的常量，都是公有的 static 常量，允许省略 public、final、static 修饰符。', 1, 326, 2),
(443, 179, '接口中的抽象方法', '接口体中定义的方法全部都是公有的抽象方法，允许省略 public、abstract 修饰符。', 1, 326, 3),
(444, 180, '接口实现（接口继承）', '接口与实现该接口的类之间的关系称为接口实现或接口继承。Java 语言是一种单继承语言，一个类只能有一个父类。然而，一个类可以实现多个接口。通过接口机制，Java 语言也能实现多继承的效果。', 1, 326, 1),
(445, 180, '接口编译为独立的字节码文件', '虽然接口不是类，但是 Java 语言把接口看做一种特殊的类。与类一样，每个接口被编译为独立的字节码文件。', 1, 327, 1),
(446, 180, '接口组织不相关类', '接口可将一组不相关的类组织在一起。例如，水果类 Fruit、鲈鱼类 Bass、白菜类 Cabbage，从概念上讲，是不相关的，但是通过接口 Eatable 可以组织在一起。', 1, 327, 2),
(447, 180, '接口回调', '当传递给接口类型变量的对象的实际类型不同时，就会回调不同类实现的接口方法，这也被称为接口回调。接口回调也是一种多态性的体现，即相同的方法调用产生不同的行为，其本质是接口类型变量可以指向实现了接口的不同具体类的对象。', 1, 329, 1),
(448, 181, '父接口与子接口', '声明的接口可以扩展（或继承）多个指定的接口，不能扩展类。被声明的接口是子接口，被扩展的接口是父接口（或超级接口）。子接口会继承所有父接口的成员。', 1, 329, 1),
(449, 182, '默认方法', '自 Java 8 开始，接口中的方法是允许有默认实现的，称为默认方法。使用关键字 default 定义默认方法。', 1, 329, 1),
(450, 182, '默认方法的重写与使用', '默认方法在实现该接口的类中可以被重写，也可以无须进行重写。如果没有对默认方法进行重写，通过接口变量调用默认方法，使用的方法实现都是默认实现。', 1, 329, 2),
(451, 182, '接口中的公有静态方法', '从 Java 8 开始，允许在接口中定义公有静态方法。公有静态方法可以通过接口名直接调用，与类中公有静态方法的使用是一样的。', 1, 329, 3),
(452, 182, '接口中的私有方法', '从 Java 9 开始，允许在接口中定义私有方法。这些私有方法的用法有限，只能作为接口中其他方法的辅助方法。', 1, 330, 1),
(453, 183, '接口与父类冲突（父类优先）', '（1）接口与父类冲突。如果父类提供了一个具体方法，那么接口中具有相同方法签名的默认方法会被忽略，即采取父类优先的原则。', 1, 330, 1),
(454, 183, '接口冲突', '（2）接口冲突。如果一个接口提供了一个默认方法，另一个接口提供了一个方法签名相同的方法，那么必须重写这个方法来解决冲突。', 1, 330, 2),
(455, 184, '密封接口', '如果一个接口的所有直接子类或子接口是已知的，那么该接口可以被声明为密封的（sealed），即密封接口。与密封类相似，Java 语言可以使用关键字 sealed 对接口进行密封，使用关键字 permits 指定允许的实现类和子接口。', 1, 332, 1),
(456, 185, '注解（Annotation）', 'Java 语言从 Java 5 开始引入了注解(Annotation)。注解提供了一种在编译时和运行时把元数据和程序元素相关联的途径。Java 语言允许对包、类、方法、字段、参数、变量和构造方法等程序元素进行注解。', 1, 332, 1),
(457, 185, 'Java 内建注解', 'Java 语言提供了三种内建注解：@Override、@Deprecated、@SuppressWarnings，如表 7-7 所示。这些注解类型包含在 java.lang 包中。', 1, 333, 1),
(458, 185, '元注解', 'Java 语言有四种元注解：@Document、@Target、@Inherited、@Retention，如表 7-8 示。', 1, 333, 2),
(459, 185, '注解接口', '除了 Java 语言提供的 3 种内建注解和 4 种元注解，开发人员还可以通过声明注解接口，创建自定义注解。', 1, 333, 3),
(460, 185, '注解方法的返回值类型', '注解方法返回值类型限定为：基本数据类型、String、enum 类型、注解接口类型、Class、或者是这些类型的数组。', 1, 334, 1),
(461, 185, '自定义注解的三种类型', '自定义注解可以有三种类型：标记注解（marker annotation）、单值注解（single value annotation）、多值注解(multivalue annotation)。标记注解没有参数，单值注解有一个参数，多值注解有多个参数。', 1, 334, 2),
(462, 186, 'Comparable 接口', 'Java 语言提供了 java.lang.Comparable 接口，用于两个相同类型对象之间的比较。例如，接口 Comparable 可用于比较两个平面封闭形状对象（比较的依据可以是面积或周长）', 1, 335, 1),
(463, 186, 'compareTo 方法', '该接口只有一个抽象方法 compareTo，该方法比较当前对象与给定对象 o 之间的顺序，如果当前对象大于、等于或小于给定对象 o 时，compareTo 方法分别返回正整数、零或负整数。', 1, 336, 1),
(464, 186, 'Comparable 是泛型接口', 'Comparable 接口是一个泛型接口，泛型参数 T 可以替换为某种具体的引用类型。在 Java 语言的类库中，许多类都实现了 Comparable 接口。', 1, 336, 2),
(465, 186, 'Arrays.sort 使用 compareTo 排序', 'java.util.Arrays.sort(Object[ ])方法可以使用接口 Comparable 的方法 compareTo 对数组中的对象进行比较。', 1, 338, 1),
(466, 187, '抽象类与接口的不同', '抽象类与接口也有不同。抽象类用于一组相关类的组织，接口可用于一组不相关类的组织。一个类只能扩展一个抽象类，但是可以扩展（实现）多个接口。抽象类可以有常量和变量，接口只有公有的静态常量。抽象类可以有构造方法，接口没有构造方法。', 1, 339, 1),
(467, 187, '引入接口的原因', '一个重要的原因是，Java 语言是一种单继承语言，引入接口可以达到多继承的效果，同时避免了多重继承的复杂性。', 1, 339, 2),
(468, 187, '抽象类与接口的选择', '在软件开发过程中，清晰描述父子关系强的“是一种”关系，可应用抽象类。而描述父子关系弱的“是一种”关系，可应用接口。', 1, 340, 1),
(469, 187, '优先使用接口', '通常情况下，应优先使用接口而不是抽象类，因为接口比抽象类更加灵活，可以为不相关类声明共同的父类型。', 1, 340, 2),
(470, 188, 'SOLID 原则', '在面向对象方法中，SOLID（单一功能、开闭原则、里氏替换、接口隔离以及依赖倒置）是首字母缩略字，指代面向对象程序设计的五个基本原则。', 1, 340, 1),
(471, 188, '单一职责原则', '单一职责原则（Single Responsibility Principle）又称单一功能原则，它规定一个类应该只有一个发生变化的原因。所谓职责是指类变化的原因。', 1, 340, 2),
(472, 188, '开闭原则', '开闭原则（Open Closed Principle）是指软件中的对象（类、模块、函数等等）应该对于扩展是开放的，但是对于修改是封闭的。这意味着一个软件允许在不改变它的现有源代码的前提下，通过新增代码来变更或扩展它的行为。', 1, 340, 3),
(473, 188, '里氏替换原则', '里氏替换原则的内容可以描述为：子类对象可以在程序中代替其父类对象。当一个方法的形式参数是父类对象时，传递的实际参数可以是其子类对象。', 1, 340, 4),
(474, 188, '接口隔离原则', '接口隔离原则（Interface Segregation Principle）是指客户端不应该依赖它不需要的接口。一个类对另一个类的依赖应该建立在最小数量的接口上。', 1, 340, 5),
(475, 188, '依赖倒置原则', '依赖倒置原则（Dependence Inversion Principle）是指程序要依赖于抽象接口，不要依赖于具体实现。这个原则就是要求对抽象进行编程，不要对实现进行编程，这样就降低了客户与实现模块间的耦合。', 1, 340, 6),
(476, 190, '继承先辈优秀遗产，发扬创新', '父类与子类的关系体现了继承与发扬，既要继承父类已有的数据域和功能，又要有变化和新增。', 1, 341, 1),
(477, 191, '树立坚定不移推进高水平对外开放的意识', '接口具有开放性，其他类如果有需要都可实现接口，比如：圆和矩形可以实现 Comparable 接口，其他形状，如，五边形、六边形也可以实现接口。', 1, 341, 1);
INSERT INTO `knowledge_code_snippet` (`id`, `chapter_id`, `title`, `code`, `is_key_example`, `page`, `page_order`) VALUES
(372, 160, '在父类基础上定义子类的一般语法形式', 'public class 子类名 extends 父类名 {\n      子类的新成员\n}', 0, 290, 1),
(373, 160, '程序清单 7-1　Account.java', '1  public class Account {\n2      private String ID;               //用户身份证号：18 位\n3      private String name;             //用户姓名\n4      private String accID;            //账户的账号：19 位\n5      private String dateCreated;      //开户日期\n6      private String createBankInfo;   //开户银行信息\n7      public Account(String iD, String name) {\n8          this(iD, name, null, null);\n9      }\n10     public Account(String iD, String name, String accID) {\n11         this(iD, name, accID, null);\n12     }\n13     public Account(String iD, String name, String accID, String createBankInfo) {\n14         ID = iD;\n15         this.name = name;\n16         this.accID = accID;\n17         this.dateCreated = new Date();\n18         this.createBankInfo = createBankInfo;\n19     }\n20     public String getID() {\n21         return ID;\n22     }\n23     public void setID(String iD) {\n24         ID = iD;\n25     }\n26     public String getName() {\n27         return name;\n28     }\n29     public void setName(String name) {\n30         this.name = name;\n31     }\n32     public String getAccID() {\n33         return accID;\n34     }\n35     public void setAccID(String accID) {\n36         this.accID = accID;\n37     }\n38     public Date getDateCreated() {\n39         return dateCreated;\n40     }\n41     public void setDateCreated(Date dateCreated) {\n42         this.dateCreated = dateCreated;\n43     }\n44     public String getCreateBankInfo() {\n45         return createBankInfo;\n46     }\n47     public void setCreateBankInfo(String createBankInfo) {\n48         this.createBankInfo = createBankInfo;\n49     }\n50     public String toString(){\n51         return "账户姓名：" + name + "\\n 账户账号：" + accID +\n52             "\\n 创建时间：" + dateCreated + "\\n 开户行：" + createBankInfo;\n53     }\n54 }', 0, 292, 2),
(374, 160, '程序清单 7-2　DebitCardAccount.java', '1  public class DebitCardAccount extends Account {\n2      private double balance;        //借记卡账户余额\n3      private double annualIntrstRate; //借记卡账户年利率\n4      public DebitCardAccount(String iD, String name) {\n5          super(iD, name);\n6      }\n7      public DebitCardAccount(String iD, String name, double balance) {\n8          super(iD, name);\n9          this.balance = balance;\n10     }\n11     public DebitCardAccount(String iD, String name, double balance,\n12         double annualIntrstRate) {\n13         super(iD, name);\n14         this.balance = balance;\n15         this.annualIntrstRate = annualIntrstRate;\n16     }\n17     public double getBalance() {\n18         return balance;\n19     }\n20     public void setBalance(double balance) {\n21         this.balance = balance;\n22     }\n23     public double getAnnualIntrstRate() {\n24         return annualIntrstRate;\n25     }\n26     public void setAnnualIntrstRate(double annualIntrstRate) {\n27         this.annualIntrstRate = annualIntrstRate;\n28     }\n29     //存款\n30     public void deposit(double d){\n31         balance += d;\n32     }\n33     //取款\n34     public boolean withdraw(double d){\n35         if(balance < d)\n36             return false;\n37         balance -= d;\n38         return true;\n39     }\n40     //获取月利率\n41     public double getMonthIntrRate(){\n42         return annualIntrstRate / 12;\n43     }\n44     //获取月利息\n45     public double getMonthIntr(){\n46         return this.getAnnualIntrstRate() * balance;\n47     }\n48     @Override\n49     public String toString(){\n50         return super.toString() + "\\n 账户类型：借记卡" +\n51             "\\n 账户余额：" + balance +\n52             "\\n 年利率：" + annualIntrstRate;\n53     }\n54 }', 0, 293, 3),
(375, 160, '程序清单 7-3　CreditCardAccount.java', '1  public class CreditCardAccount extends Account {\n2      private double creditLine; //透支额度\n3      //负债，正值表示信用卡账户有余额，负值表示欠款\n4      private double debt;\n5      private String dateRepayment; //还款日期，如："每月 20 日"\n6      private String dateBook;         //记账日期，如："每月 10 日"\n7      private double overdueIntrstRate = 0.03; //逾期利率\n8      public CreditCardAccount(String iD, String name) {\n9          super(iD, name);\n10     }\n11     public CreditCardAccount(String iD, String name, double creditLine,\n12         String dateRepayment, String dateBook) {\n13         this(iD, name, creditLine, 0, null, null, 0.03);\n14     }\n15     public CreditCardAccount(String iD, String name, double creditLine, double debt,\n16         String dateRepayment, String dateBook, double overdueIntrstRate) {\n17         super(iD, name);\n18         this.creditLine = creditLine;\n19         this.debt = debt;\n20         this.dateRepayment = dateRepayment;\n21         this.dateBook = dateBook;\n22         this.overdueIntrstRate = overdueIntrstRate;\n23     }\n24     public double getCreditLine() {\n25         return creditLine;\n26     }\n27     public void setCreditLine(double creditLine) {\n28         this.creditLine = creditLine;\n29     }\n30     public double getDebt() {\n31         return debt;\n32     }\n33     public void setDebt(double debt) {\n34         this.debt = debt;\n35     }\n36     public String getDateRepayment() {\n37         return dateRepayment;\n38     }\n39     public void setDateRepayment(String dateRepayment) {\n40         this.dateRepayment = dateRepayment;\n41     }\n42     public String getDateBook() {\n43         return dateBook;\n44     }\n45     public void setDateBook(String dateBook) {\n46         this.dateBook = dateBook;\n47     }\n48     public double getOverdueIntrstRate() {\n49         return overdueIntrstRate;\n50     }\n51     public void setOverdueIntrstRate(double overdueIntrstRate) {\n52         this.overdueIntrstRate = overdueIntrstRate;\n53     }\n54     //支出\n55     public boolean expand(double d){\n56         if(Math.abs(debt - d) > creditLine)\n57             return false;\n58         debt -= d;\n59         return true;\n60     }\n61     //还款\n62     public void repayment(double d){\n63         debt += d;\n64     }\n65     @Override\n66     public String toString(){\n67         return super.toString() + "\\n 账户类型：信用卡" +\n68             "\\n 信用额度:" + creditLine + "\\n 负债:" + debt +\n69             "\\n 还款日期:" + dateRepayment;\n70     }\n71 }', 0, 294, 4),
(376, 160, '程序清单 7-4　TestCreditDebitAccount.java', '1  public class TestDebitCreditAccount {\n2      public static void main(String[] args) {\n3          String name1 = "张三";\n4          String ID1 = "450309200010100019";\n5          String accID1 = "6220028898837993323";\n6          DebitCardAccount acc1 = new DebitCardAccount(ID1, name1);\n7          acc1.setAccID(accID1);\n8          acc1.setCreateBankInfo("交通银行桂林分行");\n9          acc1.setBalance(50000);\n10         acc1.withdraw(5000);\n11         acc1.setAnnualIntrstRate(0.015);\n12         System.out.println("账户姓名：" + acc1.getName() +\n13             "\\n 账户账号：" + acc1.getAccID() +\n14             "\\n 账户余额：" + acc1.getBalance());\n15         String name2 = "小红";\n16         String ID2 = "450552200212210027";\n17         String accID2 = "6283028898837993323";\n18         CreditCardAccount acc2 = new CreditCardAccount(ID2, name2);\n19\n20         acc2.setAccID(accID2);\n21         acc2.setCreateBankInfo("中国银行桂林分行");\n22         acc2.setCreditLine(50000);\n23         acc2.setDebt(-40000);\n24         acc2.expand(5000);\n25         acc2.setDateRepayment("每月 20 日");\n26         System.out.println("---------------");\n27         System.out.println("账户姓名：" + acc2.getName() +\n28             "\\n 账户账号：" + acc2.getAccID() +\n29             "\\n 账户负债：" + acc2.getDebt());\n30         System.out.println("***************");\n31         System.out.println(acc1.toString());\n32         System.out.println("---------------");\n33         System.out.println(acc2.toString());\n34     }\n35 }', 0, 296, 5),
(377, 160, '程序清单 7-4 运行结果', '账户姓名：张三\n账户账号：6220028898837993323\n账户余额：45000.0\n---------------\n账户姓名：小红\n账户账号：6283028898837993323\n账户负债：-45000.0\n***************\n账户姓名：张三\n账户账号：6220028898837993323\n创建时间：Fri Jan 27 14:09:22 CST 2023\n开户行：交通银行桂林分行\n账户类型：借记卡\n账户余额：45000.0\n年利率：0.015\n---------------\n账户姓名：小红\n账户账号：6283028898837993323\n创建时间：Fri Jan 27 14:09:22 CST 2023\n开户行：中国银行桂林分行\n账户类型：信用卡\n信用额度:50000.0\n负债:-45000.0\n还款日期:每月 20 日', 0, 297, 6),
(378, 161, '图 7-3 可见性修饰符使用示例（跨包访问）', 'package p1;\npublic class C1{\n      public int a;\n      protected int b;\n      int c;\n      private int d;\n      protected void m1(){}\n}\nclass C2{\n      public int x;\n      protected int y;\n      int z;\n      private int w;\n      protected void m2(){}\n}\npublic class C3\n      extends C1 {\n      能访问 a,b,c;\n      不能访问 d；\n      能调用 m1();\n}\npublic class T1{\n      C1 o1 = new C1();\n      C2 o2 = new C2();\n      能：o1.a,o1.b,\n          o1.c,o2.x,o2.y,o2.z，\n          o1.m1(),o2.m2();\n      不能：o1.d, o2.w;\n}\n\npackage p2;\npublic class C4\nextends C1 {\n      可访问 a,b;\n      不能访问 c,d；\n      能调用 m1();\n}\npublic class T2{\n      C1 o1 = new C1();\n      能：o1.a, o1.m1();\n      不能：o1.b, o1.c, o1.d, o1.m1();\n      不能访问类 C2；\n}', 0, 300, 7),
(379, 163, '显式调用父类构造方法的两种语法形式', 'super( );  //无参构造方法\nsuper(实际参数列表); //带参数构造方法', 0, 300, 8),
(380, 163, '图 7-4 编译器自动放置 super( ) 的等价代码', 'public class SubClass{                    等价    public SubClass( ){\n   public SubClass( ){                             super( );\n      //子类初始化语句                                //子类初始化语句\n   }\n   public SubClass(形式参数列表){                  }\n      //子类初始化语句\n   }                                  等价     public SubClass(形式参数列表){\n      //其他代码略                                 super( );\n}                                              //子类初始化语句\n                                           }', 0, 300, 9),
(381, 163, '程序清单 7-5　ClsD.java', '1  public class ClsD extends ClsC {\n2      public static void main(String[] args) {\n3          new ClsD();\n4      }\n5      public ClsD(){\n6          System.out.println("ClsD 的构造方法执行！");\n7      }\n8  }\n9  class ClsC extends ClsB {\n10     public ClsC(){\n11         this("ClsC 的构造方法执行!");\n12     }\n13     public ClsC(String s){\n14         System.out.println(s);\n15     }\n16 }\n17 class ClsB extends ClsA {\n18     public ClsB(){\n19         System.out.println("ClsB 的构造方法执行！");\n20     }\n21 }\n22 class ClsA {\n23     public ClsA(){\n24         System.out.println("ClsA 的构造方法执行！");\n25     }\n26 }', 0, 301, 10),
(382, 163, '程序清单 7-5 运行结果', 'ClsA 的构造方法执行！\nClsB 的构造方法执行！\nClsC 的构造方法执行!\nClsD 的构造方法执行！', 0, 301, 11),
(383, 164, 'super 调用父类普通方法的语法形式', 'super.方法名( );   //调用父类无参数的普通方法\nsuper.方法名(实际参数列表); //调用父类有参数的普通方法', 0, 302, 12),
(384, 164, '图 7-6 重写 toString( ) 并用 super 调用父类方法的两个代码段', '// 图 7-6 代码段 1\n@Override\npublic String toString(){\n      return super.toString() + "\\n 用户类型：" + type\n                  +"\\n 余额："+ super.getBalance();\n}\n// 图 7-6 代码段 2\n@Override\npublic String toString(){\n      return super.toString() + "\\n 信用额度:" + creditLine\n                              + "\\n 负债:" + debt;\n}', 0, 302, 13),
(385, 166, 'final 修饰不可被继承的最终类', 'public final class ClsA{\n      …\n}', 0, 303, 14),
(386, 166, 'final 修饰不可被子类重写的最终方法', 'public class ClsB{\n      //….\n      public final void m1(){\n         //…\n       }\n}', 0, 303, 15),
(387, 167, '密封抽象类 Shape 用 permits 列出允许的子类', 'package edu.example.Chapter 7;\npublic abstract sealed class Shape\n      permits Circle, Rect, Triangle{\n         …\n}', 0, 304, 16),
(388, 167, '允许的子类在不同包时 permits 需给出完整路径', 'package edu.example.Chapter 7;\npublic abstract sealed class Shape\n      permits edu.example.geometry.Circle,\n               edu.example.shape1.Rect,\n               edu.exmaple.shape2.Triangle{\n      …\n}', 0, 304, 17),
(389, 167, '同一源文件内声明子类时可省略 permits 语句', 'public abstract sealed class ClsRoot{\n      …\n      final class ClsA extends ClsRoot{…}\n      final class ClsB extends ClsRoot{…}\n      final class ClsC extends ClsRoot{…}\n}', 0, 304, 18),
(390, 167, '密封类子类使用 final、sealed、non-sealed 修饰符示例', '[1]行: package edu.example.Chapter 7;\n[2]行: public abstract sealed class Shape\n                  permits Circle, Rect, Triangle, OddShape{ … }\n[3]行: pulic final class Circle extends Shape { … }\n[4]行: public sealed class Rect extends Shape permits FilledRect, TransparentRect { … }\n[5]行: public final class FilledRect extends Rect{ … }\n[6]行: public final class TransparentRect extends Rect{ … }\n[7]行: public non-sealed class OddShape extends Shape { … }', 0, 305, 19),
(391, 168, '图 7-7 未指定父类时默认继承 Object 的等价代码', 'public class ClsA{                     等价     public class ClsA extends Object{\n   …                                                  …\n}                                                 }', 0, 305, 20),
(392, 169, '类 Object 的方法 toString( ) 的方法头', 'public String toString( )', 0, 306, 21),
(393, 169, '程序清单 7-6　SimpleCircle.java', '1  package chapter7;\n2  public class SimpleCircle {\n3      private double radius;\n4      public static void main(String[] args) {\n5          SimpleCircle circle = new SimpleCircle();\n6          System.out.println(circle.toString());\n7      }\n8  }', 0, 306, 22),
(394, 169, '程序清单 7-6 运行结果', 'chapter7.SimpleCircle@15db9742', 0, 306, 23),
(395, 169, '程序清单 7-7　SimpleCircle1.java', '1  public class SimpleCircle1 {\n2      private double radius;\n3      @Override\n4      public String toString(){\n5          return "半径：" + radius + "；周长：" + 2 * 3.14 * radius;\n6      }\n7      public static void main(String[] args) {\n8          SimpleCircle1 circle = new SimpleCircle1();\n9          circle.radius = 2;\n10         System.out.println("对象 circle 信息：\\n" + circle);\n11     }\n12 }', 0, 306, 24),
(396, 169, '程序清单 7-7 运行结果', '圆对象 circle 信息：\n圆半径：2.0；圆周长：12.56', 0, 307, 25),
(397, 170, '类 Object 的方法 equals( ) 的方法头', 'public boolean equals(Object obj)', 0, 307, 26),
(398, 170, '调用 equals( ) 比较两个对象的一般形式', 'object1.equals(object2);          //对象 object1 与 object2 进行相等比较', 0, 307, 27),
(399, 170, '类 Object 的 equals 方法的默认实现', 'public boolean equals(Object obj){\n       return (this == obj)\n}', 0, 307, 28),
(400, 170, '创建三个字符串对象 s1、s2、s3 的示例', 'String s1 = new String("Hello");\nString s2 = "Hello";\nString s3 = "Hello";', 0, 307, 29),
(401, 170, '程序清单 7-8　Circle1.java', '1  public class Circle1 {\n2      private double radius;\n3      @Override\n4      public boolean equals(Object obj){\n5          //instanceof 运算符，判断一个对象是否某个类的实例\n6          if(obj instanceof Circle1)\n7              return radius == ((Circle1)obj).radius;\n8          else\n9              return false;\n10     }\n11     @Override\n12     public String toString(){\n13         return "圆半径：" + radius;\n14     }\n15     public static void main(String[] args) {\n16         Circle1 c1 = new Circle1();\n17         c1.radius = 3;\n18         Circle1 c2 = new Circle1();\n19         c2.radius = 3;\n20         //等价于 System.out.println("c1" + c1.toString())\n21         System.out.println("c1" + c1);\n22         System.out.println("c2" + c2);\n23         System.out.println("c1 与 c2 相等：" + c1.equals(c2));\n24         //修改 c2 的圆半径为 5\n25         c2.radius = 5;\n26         System.out.println("c2" + c2);\n27         System.out.println("c1 与 c2 相等：" + c1.equals(c2));\n28     }\n29 }', 0, 308, 30),
(402, 170, '程序清单 7-8 运行结果', 'c1 圆半径：3.0\nc2 圆半径：3.0\nc1 与 c2 相等：true\nc2 圆半径：5.0\nc1 与 c2 相等：false', 0, 308, 31),
(403, 171, '程序清单 7-9　Shape.java', '1  public class Shape {\n2      private String strokedColor = "Black";\n3      private String filledColor = "White";\n4      private Date timeCreated;\n5      public Shape(){\n6          timeCreated = new Date();\n7      }\n8      public Shape(String sColor, String fColor){\n9          strokedColor = sColor;\n10         filledColor = fColor;\n11     }\n12     public double getArea(){\n13         return 0.0;\n14     }\n15     @Override\n16     public String toString(){\n17         return "创建于：" + timeCreated + ";画线颜色："\n18             + strokedColor + ";填充颜色：" + filledColor;\n19     }\n20     public String getStrokedColor() {\n21         return strokedColor;\n22     }\n23     public void setStrokedColor(String strokedColor) {\n24         this.strokedColor = strokedColor;\n25     }\n26     public String getFilledColor() {\n27         return filledColor;\n28     }\n29     public void setFilledColor(String filledColor) {\n30         this.filledColor = filledColor;\n31     }\n32     public Date getTimeCreated() {\n33         return timeCreated;\n34     }\n35     public void setTimeCreated(Date timeCreated) {\n36         this.timeCreated = timeCreated;\n37     }\n38 }', 0, 309, 32),
(404, 171, '程序清单 7-10　Circle.java', '1  public class Circle extends Shape {\n2      private double radius;\n3      final static double PI = 3.14;\n4      public Circle(){\n5          this(1.0);\n6      }\n7      public Circle(double r){\n8          setRadius(r);\n9      }\n10     @Override\n11     public double getArea(){\n12         return PI * getRadius() * getRadius();\n13     }\n14     @Override\n15     public String toString(){\n16         return super.toString() + "\\n 半径：" + getRadius();\n17     }\n18     public double getRadius() {\n19         return radius;\n20     }\n21     public void setRadius(double radius) {\n22         this.radius = radius;\n23     }\n24 }', 0, 310, 33),
(405, 171, '程序清单 7-11　Rect.java', '1  public class Rect extends Shape {\n2      private double length;//矩形长\n3      private double width; //矩形宽\n4      public Rect(){\n5          this(1, 1);\n6      }\n7      public Rect(double width, double length){\n8          this.setWidth(width);\n9          this.setLength(length);\n10     }\n11     @Override\n12     public double getArea(){\n13         return getWidth() * getLength();\n14     }\n15     @Override\n16     public String toString(){\n17         return super.toString() + "\\n 长：" + getLength() +\n18             ";宽：" + getWidth();\n19     }\n20     public double getLength() {\n21         return length;\n22     }\n23     public void setLength(double length) {\n24         this.length = length;\n25     }\n26     public double getWidth() {\n27         return width;\n28     }\n29     public void setWidth(double width) {\n30         this.width = width;\n31     }\n32 }', 0, 310, 34),
(406, 171, '程序清单 7-12　TestShapes.java', '1  public class TestShapes {\n2      public static void display(Shape s){\n3          System.out.println(s.toString() + ". 面积:"+ s.getArea());\n4      }\n5      public static void main(String[] args) {\n6          Circle c = new Circle(5.5);\n7          Rect r = new Rect(3.5, 4.5);\n8          Shape s = c;\n9          display(s); //s 指向一个圆对象 c\n10         s = r;\n11         display(s); //s 指向一个矩形对象 r\n12     }\n13 }', 0, 311, 35),
(407, 171, '程序清单 7-12 运行结果', '创建于：Sat Jan 07 09:07:34 CST 2023;画线颜色：Black;填充颜色：White\n半径：5.5. 面积:94.985\n创建于：Sat Jan 07 09:07:34 CST 2023;画线颜色：Black;填充颜色：White\n长：4.5;宽：3.5. 面积:15.75', 0, 311, 36),
(408, 172, '方法 display 通过父类引用变量调用被重写的方法', 'public static void display(Shape s){\n      System.out.println(s.toString() + ". 面积:"+ s.getArea());\n}', 0, 312, 37),
(409, 172, '程序清单 7-13　Cuboid.java', '1  public class Cuboid extends Rect {\n2      private double height; //长方体的高\n3      public Cuboid(){\n4          this(1,1,1);\n5      }\n6      public Cuboid(double l, double w, double h){\n7          super(l,w);\n8          height = h;\n9      }\n10     public static void main(String[] args){\n11         Cuboid cuboid = new Cuboid();\n12         TestShapes.display(cuboid);\n13     }\n14 }', 0, 313, 38),
(410, 172, '程序清单 7-13 运行结果', '创建于：Sat Jan 07 11:30:30 CST 2023;画线颜色：Black;填充颜色：White\n长：1.0;宽：1.0. 面积:1.0', 0, 313, 39),
(411, 173, '子类引用变量直接指向父类对象（编译错误）', 'Circle c2 = s; //子类引用变量指向父类对象', 0, 313, 40),
(412, 173, '用显式转换把父类引用变量转换成子类引用变量', 'Circle c2 = (Circle)s; //显式转换', 0, 313, 41),
(413, 173, '向下转换到不相容子类产生运行时错误', 'Shape s = new Circle(); //合法正确，s 指向一个 Circle 的实例\nRect r2 = (Rect)s;      //产生运行时错误', 0, 314, 42),
(414, 173, '向下转换前用 instanceof 判断父类引用变量的实际类型', 'void display(Shape s){\n    if(s instanceof Circle) //判断 s 是否指向类 Circle 的一个实例\n        System.out.println(“这是一个圆，半径为：” + ((Circle)s).getRadius());\n    …\n}', 0, 314, 43),
(415, 174, '定义公有抽象类的一般形式', 'public abstract class 类名{….} //一个公有抽象类的定义', 0, 314, 44),
(416, 174, '定义公有抽象方法的一般形式', 'public abstract 返回值类型 方法名(形式参数列表); //一个公有抽象方法定义', 0, 314, 45),
(417, 174, '程序清单 7-14　ShapeObj.java', '1  public abstract class ShapeObj { //抽象类定义\n2      private String strokedColor = "Black";\n3      private String filledColor = "White";\n4      private Date timeCreated;\n5      public ShapeObj(){\n6          setTimeCreated(new Date());\n7      }\n8      public ShapeObj(String sColor, String fColor){\n9          setStrokedColor(sColor);\n10         setFilledColor(fColor);\n11     }\n12     public abstract double getArea();        //抽象方法定义，无方法体\n13     public abstract double getPerimeter(); //抽象方法定义，无方法体\n14     @Override\n15     public String toString(){\n16         return "创建于：" + getTimeCreated() + ";画线颜色："\n17             + getStrokedColor() + ";填充颜色：" + getFilledColor();\n18     }\n19     public String getStrokedColor() {\n20         return strokedColor;\n21     }\n22     public void setStrokedColor(String strokedColor) {\n23         this.strokedColor = strokedColor;\n24     }\n25     public String getFilledColor() {\n26         return filledColor;\n27     }\n28     public void setFilledColor(String filledColor) {\n29         this.filledColor = filledColor;\n30     }\n31     public Date getTimeCreated() {\n32         return timeCreated;\n33     }\n34     public void setTimeCreated(Date timeCreated) {\n35         this.timeCreated = timeCreated;\n36     }\n37 }', 0, 315, 46),
(418, 174, '程序清单 7-15　CircleObj.java', '1  public class CircleObj extends ShapeObj {\n2      private double radius;\n3      final static double PI = 3.14;\n4      public CircleObj(){\n5          this(1.0);\n6      }\n7      public CircleObj(double r){\n8          setRadius(r);\n9      }\n10     @Override\n11     public double getArea(){\n12         return PI * getRadius() * getRadius();\n13     }\n14     @Override\n15     public double getPerimeter(){\n16         return 2 * PI * getRadius();\n17     }\n18     @Override\n19     public String toString(){\n20         return super.toString() + "\\n 半径：" + getRadius();\n21     }\n22     public double getRadius() {\n23         return radius;\n24     }\n25     public void setRadius(double radius) {\n26         this.radius = radius;\n27     }\n28 }', 0, 316, 47),
(419, 174, '程序清单 7-16　RectObj.java', '1  public class RectObj extends ShapeObj {\n2      private double length;//矩形长\n3      private double width; //矩形宽\n4      public RectObj(){\n5          this(1, 1);\n6      }\n7      public RectObj(double width, double length){\n8          this.setWidth(width);\n9          this.setLength(length);\n10     }\n11     @Override\n12     public double getArea(){\n13         return getWidth() * getLength();\n14     }\n15     @Override\n16     public double getPerimeter(){\n17         return 2 * getWidth() * getLength();\n18     }\n19     @Override\n20     public String toString(){\n21         return super.toString() + "\\n 长：" + getLength() +\n22             ";宽：" + getWidth();\n23     }\n24     public double getLength() {\n25         return length;\n26     }\n27     public void setLength(double length) {\n28         this.length = length;\n29     }\n30     public double getWidth() {\n31         return width;\n32     }\n33     public void setWidth(double width) {\n34         this.width = width;\n35     }\n36 }', 0, 316, 48),
(420, 174, '程序清单 7-17　TestShapeObjs.java', '1  public class TestShapeObjs {\n2      public static void displayObj(ShapeObj sObj){\n3          System.out.println(sObj);\n4          System.out.println("面积："+sObj.getArea());\n5       System.out.println("周长："+sObj.getPerimeter());\n6      }\n7      public static boolean equalsArea(ShapeObj sObj1, ShapeObj sObj2){\n8          return sObj1.getArea() == sObj2.getArea();\n9      }\n10     public static void main(String[] args) {\n11         CircleObj c = new CircleObj(4.5);\n12         RectObj r = new RectObj(3, 4);\n13         displayObj(c);\n14         displayObj(r);\n15         System.out.println("形状 c 和形状 r 具有相同面积？" + equalsArea(c, r));\n16         ShapeObj sObj = new CircleObj(3);\n17         sObj.setFilledColor("Red");\n18         sObj.setStrokedColor("Blue");\n19         displayObj(sObj);\n20     }\n21 }', 0, 317, 49),
