(426, 176, '程序清单 7-18　TestCalendar.java', '1  public class TestCalendar {\n2      public static void main(String[] args) {\n3          //以当前时间创建一个日历对象\n4          Calendar calendar = new GregorianCalendar();\n5          System.out.println("当前时间：" + new Date());\n6          System.out.println("年:\\t" + calendar.get(Calendar.YEAR));\n7          System.out.println("月:\\t" + monthName(calendar.get(Calendar.MONTH)));\n8          System.out.println("日:\\t" + calendar.get(Calendar.DATE));\n9          System.out.println("时（12 小时制）:\\t" + calendar.get(Calendar.HOUR));\n10         System.out.println("时（24 小时制）:\\t" +\n11             calendar.get(Calendar.HOUR_OF_DAY));\n12         System.out.println("分:\\t" + calendar.get(Calendar.MINUTE));\n13         System.out.println("秒:\\t" + calendar.get(Calendar.SECOND));\n14         System.out.println("星期几:\\t" +\n15             calendar.get(Calendar.DAY_OF_WEEK));\n16         System.out.println("当月的日数:\\t" +\n17             calendar. getMaximum (Calendar.DAY_OF_MONTH));\n18         System.out.println("当年的天数:\\t" +\n19             calendar.get(Calendar.DAY_OF_YEAR));\n20         System.out.println("当月的周数:\\t" +\n21             calendar.get(Calendar.WEEK_OF_MONTH));\n22         System.out.println("当年的周数:\\t" +\n23             calendar.get(Calendar.WEEK_OF_YEAR));\n24         System.out.println("上午或下午:\\t" + calendar.get(Calendar.AM_PM));\n25\n26         // 以指定时间创建一个日历对象，时间为 1949 年 10 月 1 日\n27         Calendar calendar1 = new GregorianCalendar(1949, 9, 1);\n28         System.out.println("1949 年 10 月 1 日的日历信息：");\n29         System.out.println("星期几:\\t" +\n30             dayNameOfWeek(calendar1.get(Calendar.DAY_OF_WEEK)));\n31         System.out.println("当年的周数:\\t" +\n32             calendar1.get(Calendar.WEEK_OF_YEAR));\n33         System.out.println("当月的周数:\\t" +\n34             calendar1.get(Calendar.WEEK_OF_MONTH));\n35\n36         //设置日期域为 10，并增加 5 天\n37         calendar1.set(Calendar.DATE, 10);\n38         calendar1.add(Calendar.DATE, 5);\n39         System.out.println("-----修改之后-----");\n40         System.out.println("年:\\t" + calendar1.get(Calendar.YEAR));\n41         System.out.println("月:\\t" + monthName(calendar1.get(Calendar.MONTH)));\n42         System.out.println("日:\\t" + calendar1.get(Calendar.DATE));\n43     }\n44     public static String monthName(int month){\n45         switch (month) {\n46         case 0: return "一月";\n47         case 1: return "二月";\n48         case 2: return "三月";\n49         case 3: return "四月";\n50         case 4: return "五月";\n51         case 5: return "六月";\n52         case 6: return "七月";\n53         case 7: return "八月";\n54         case 8: return "九月";\n55         case 9: return "十月";\n56         case 10: return "十一月";\n57         case 11: return "十二月";\n58         default: return null;\n59         }\n60     }\n61     public static String dayNameOfWeek(int dayOfWeek) {\n62         switch (dayOfWeek) {\n63         case 1: return "SUNDAY(星期日)";\n64         case 2: return "Monday(星期一)";\n65         case 3: return "Tuesday(星期二)";\n66         case 4: return "Wednesday(星期三)";\n67         case 5: return "Thursday(星期四)";\n68         case 6: return "Friday(星期五)";\n69         case 7: return "Saturday(星期六)";\n70         default: return null;\n71         }\n72     }\n73 }', 0, 322, 55),
(427, 176, '程序清单 7-18 运行结果', '当前时间：Thu May 04 11:47:17 CST 2023\n年: 2023\n月: 五月\n日: 4\n时（12 小时制）: 11\n时（24 小时制）: 11\n分: 47\n秒: 17\n星期几: 5\n当月的日数: 31\n当年的天数: 124\n当月的周数: 1\n当年的周数: 18\n上午或下午: 0\n1949 年 10 月 1 日的日历信息：\n星期几: Saturday(星期六)\n当年的周数: 40\n当月的周数: 1\n-----修改之后-----\n年: 1949\n月: 十月\n日: 15', 0, 324, 56),
(428, 177, 'Number 中由 intValue( ) 派生的 byteValue( ) 与 shortValue( )', 'public byte byteValue(){\n      return (byte)intValue();\n}\npublic short short Value(){\n      return (short)intValue();\n}', 0, 324, 57),
(429, 177, '程序清单 7-19　TestNumberClasses.java', '1  public class TestNumberClasses {\n2      public static void main(String[] args) {\n3          Number[] nums = {10, 12.5, 23.5, 45,\n4              new BigInteger("9738743232"),\n5              new BigDecimal("1234.32434532432")};\n6          System.out.println("最小的数是：" + getMinNum(nums));\n7      }\n8      public static Number getMinNum(Number[] nums){\n9          Number min = nums[0];\n10         for(int i = 1; i < nums.length; i++)\n11         if(min.doubleValue() > nums[i].doubleValue())\n12             min = nums[i];\n13         return min;\n14     }\n15 }', 0, 325, 58),
(430, 177, '程序清单 7-19 运行结果', '最小的数是：10', 0, 325, 59),
