(447, 182, '接口中定义私有静态方法与私有实例方法示例', 'interface DemoInterface2{\n    //私有静态方法\n    private static void dislay(){\n        System.out.println(“default private implementation!”);\n    }\n    //私有实例方法\n    private int getAttribute(){\n        return 1;\n    }\n    …\n}', 0, 330, 76),
(448, 183, '程序清单 7-27　Student.java', '1  public class Student extends Person implements Name {\n2      public static void main(String[] args) {\n3          Student stu = new Student();\n4          stu.setName("张三");\n5          System.out.println("姓名：" + stu.getName());\n6      }\n7  }\n8  class Person{\n9      private String name;\n10     public String getName() {\n11         return name;\n12     }\n13     public void setName(String name) {\n14         this.name = name;\n15     }\n16 }\n17 interface Name{\n18     default String getName(){\n19         return "unset";\n20     }\n21 }', 0, 330, 77),
(449, 183, '程序清单 7-27 运行结果', '姓名：张三', 0, 331, 78),
(450, 183, '程序清单 7-28　Teacher.java', '1  public class Teacher implements Persons, Named {\n2      public static void main(String[] args) {\n3      }\n4  }\n5  interface Persons {\n6      default String getName(){\n7         return "Persons";\n8      }\n9  }\n10 interface Named {\n11     default String getName(){\n12         return "Name";\n13     }\n14 }', 0, 331, 79),
(451, 183, '默认方法冲突时 Java 编译器报告的错误信息', 'Duplicate default methods named getName with the parameters () and () are inherited from the types Named and Persons', 0, 331, 80),
