(457, 185, '带默认值的注解接口 MethodInfo 声明示例', 'public @interface MethodInfo{\n    String author() default ‘Pankaj’;\n    String date();\n    int revision() default 1;\n    String comments();\n}', 0, 333, 86),
(458, 185, '标记注解、单值注解与多值注解三种自定义注解', '@Retention(RetentionPolicy.RUNTIME)\npublic @interface Feedback {} // 标记注解\n\npublic @interface Feedback {\n    String reportName();\n} // 单值注解\n\npublic @interface Feedback {\n    String reportName();\n    String comment() default "None";\n} // 多值注解', 0, 334, 87),
(459, 185, '程序清单 7-29　MethodInfo.java', '1  @Documented\n2  @Target(ElementType.METHOD)\n3  @Inherited\n4  @Retention(RetentionPolicy.RUNTIME)\n5  public @interface MethodInfo {          //多值注解\n6      String author() default "Tom";\n7      String date();\n8      int revision() default 1;\n9      String comments();\n10 }', 0, 334, 88),
(460, 185, '程序清单 7-30　TestAnnotationInterface.java', '1  public class TestAnnotationInterface {\n2      public static void main(String[] args) {\n3      }\n4      @Override\n5      @MethodInfo(author = "William", comments = "Override method",\n6                        date = "January 1, 2023", revision = 2)\n7      public String toString() {\n8          return "Overriden toString method";\n9      }\n10     @Deprecated\n11     @MethodInfo(comments = "deprecated method", date = "January 1, 2023")\n12     public static void oldMethod() {\n13         System.out.println("old method, don’t use it.");\n14     }\n15     @SuppressWarnings({ "unchecked", "deprecation" })\n16     @MethodInfo(author = "William", comments = "Test method",\n17                     date = "January 1, 2023", revision = 3)\n18     public static void methodTest() throws FileNotFoundException {\n19         List l = new ArrayList();\n20         l.add("abc");\n21         oldMethod();\n22     }\n23 }', 0, 334, 89),
(461, 186, 'java.lang.Comparable 接口的定义', 'package java.lang;\npublic interface Comparable<T>{\n    public int compareTo(T o);\n}', 0, 336, 90),
(462, 186, '程序清单 7-31　TestComparable.java', '1  import java.util.Date;\n2  public class TestComparable {\n3      public static void main(String[] args) {\n4          System.out.println(Double.valueOf(10).compareTo(6.5));\n5          System.out.println(Double.valueOf(10).compareTo(10d));\n6          System.out.println(Integer.valueOf(10).compareTo(15));\n7          System.out.println("Hello".compareTo("hello"));\n8          @SuppressWarnings("deprecation")\n9          Date date1 = new Date(2023, 1, 1);\n10         @SuppressWarnings("deprecation")\n11         Date date2 = new Date(2023, 10, 1);\n12         System.out.println(date1.compareTo(date2));\n13     }\n14 }', 0, 336, 91),
(463, 186, '程序清单 7-31 运行结果', '1\n0\n-1\n-32\n-1', 0, 336, 92),
(464, 186, '程序清单 7-32　ComparableCircle.java', '1  public class ComparableCircle extends Circle\n2                    implements Comparable<ComparableCircle> {\n3      public ComparableCircle(double r){\n4          super(r);\n5      }\n6      @Override\n7      public int compareTo(ComparableCircle o){\n8          if(getArea() > o.getArea())\n9              return 1;\n10         else if(getArea() == o.getArea())\n11             return 0;\n12         else\n13             return -1;\n14     }\n15     @Override\n16     public String toString(){\n17         return "半径：" + this.getRadius() +\n18                  "；面积：" + this.getArea();\n19     }\n20 }', 0, 337, 93),
(465, 186, '程序清单 7-33　ComparableRect.java', '1  public class ComparableRect extends Rect\n2         implements Comparable<ComparableRect> {\n3      public ComparableRect(double length, double width){\n4          super(length, width);\n5      }\n6      @Override\n7      public int compareTo(ComparableRect o){\n8          if(getArea() > o.getArea())\n9              return 1;\n10         else if(getArea() == o.getArea())\n11             return 0;\n12         else\n13             return -1;\n14     }\n15     @Override\n16     public String toString(){\n17         return "长：" + getLength() + "；宽：" + getWidth() +\n18                  "；面积：" + getArea();\n19     }\n20 }', 0, 337, 94),
(466, 186, 'ComparableCircle 与 ComparableRect 对象的一组 instanceof 表达式', 'c1 instanceof Shape                          rect1 instanceof Shape\nc1 instanceof Circe                          rect1 instanceof Rect\nc1 instanceof ComparableCircle               rect1 instanceof ComparableRect\nc1 instanceof Comparable                     rect1 instanceof Comparable', 0, 338, 95),
(467, 186, '程序清单 7-34　TestComparableShapes.java', '1  public class TestComparableShapes {\n2      public static void main(String[] args) {\n3          Comparable<ComparableCircle> c1 = new ComparableCircle(2.5);\n4          Comparable<ComparableCircle> c2 = new ComparableCircle(2.5);\n5          System.out.println(c1.compareTo((ComparableCircle) c2));\n6\n7          ComparableRect[] rects = {\n8              new ComparableRect(12.5, 4.5),\n9              new ComparableRect(8.2, 6.5),\n10             new ComparableRect(10.3, 5.5),\n11             new ComparableRect(15.3, 3.2),\n12         };\n13         java.util.Arrays.sort(rects);\n14         for(Shape rect: rects)\n15             System.out.println(rect);\n16     }\n17 }', 0, 338, 96),
(468, 186, '程序清单 7-34 运行结果', '0\n长：15.3；宽：3.2；面积：48.96000000000001\n长：8.2；宽：6.5；面积：53.3\n长：12.5；宽：4.5；面积：56.25\n长：10.3；宽：5.5；面积：56.650000000000006', 0, 338, 97),
(469, 186, '遍历 ComparableRect 对象数组的三种 for 循环写法', 'for(Rect rect: rects)\nfor(ComparableRect: rects)\nfor(Comparable< ComparableRect > rect: rects)', 0, 339, 98);
