INSERT INTO `knowledge_difficult_point` (`id`, `chapter_id`, `description`, `type`, `page`, `page_order`) VALUES
(81, 160, '子类是否继承父类私有成员有两种说法：从内存分配（物理实现）上讲子类继承了包括私有成员在内的所有数据域，从可访问性上讲父类私有成员未被继承；教材采纳官方文档说法。构造方法不是成员，不被继承，只能被子类构造方法调用。', 3, 298, 1),
(82, 161, '表 7-1 的四列可见性是高频考点：protected 成员对同包类与不同包子类开放、对不同包的非子类关闭；包私有成员对同包类开放、不同包子类也不能访问；private 只在本类内可见。', 2, 299, 1),
(83, 163, 'super( ) 或 super(实际参数列表) 必须是子类构造方法的第一条语句；子类未显式调用时编译器自动加上 super( )，若直接父类没有无参构造方法就产生编译错误（选择题第 5、8 题考点），可被继承的类最好提供无参构造方法。', 1, 300, 1),
(84, 165, '方法重写的四个约束：方法签名相同且返回类型相同或兼容（协变）、只有子类可访问的实例方法才能被重写（私有方法不能）、不能降低可访问性、静态方法只能被隐藏而不能被重写（需用「父类名.静态方法名( )」调用）。', 2, 303, 1),
(85, 165, '重写与重载辨析：重写发生在有继承关系的不同类中、方法签名必须相同；重载可在同一类也可在不同类、方法名相同而方法签名不同。子类中定义与父类私有方法同签名的方法与父类方法毫无关系。', 3, 303, 2),
(86, 170, 'equals( ) 的默认实现就是 return (this == obj)，比较引用；String 等类重写后比较内容。new String("Hello") 与字符串常量 "Hello" 用 == 比较为 false、用 equals 比较为 true，是最常见的概念混淆点。', 3, 307, 1),
(87, 171, '「编译看左边、运行看实际对象」：display(Shape s) 中 s 指向 Circle 时执行 Circle 重写的 toString、getArea，指向 Rect 时执行 Rect 的实现；同一行代码因引用对象不同而表现不同行为，是多态的高频考点。', 2, 311, 1),
(88, 172, '声明类型与实际类型辨析：编译阶段按声明类型做方法匹配，运行阶段 JVM 按实际类型绑定实现；实际类型对应的子类若未重写，则沿继承链向 Object 方向取最近的重写实现（长方体 Cuboid 用例绑定 Rect 的方法）。静态方法不参与动态绑定。', 3, 312, 1),
(89, 173, '对象转换的易错点：Circle c2 = s 编译报错，必须写成 Circle c2 = (Circle)s；(Rect)s 在 s 实际指向 Circle 时编译通过而运行时抛 ClassCastException。类 Shape 无 getRadius 时 s.getRadius( ) 是编译错误，需先向下转换为 ((Circle)s).getRadius( )，向下转换前应使用 instanceof 判断。', 1, 314, 1),
(90, 174, '抽象类相关易错点：抽象类不能用 new 实例化，但可以声明其引用变量与对象数组元素并指向子类实例；含有抽象方法的类必须声明为抽象类，而抽象类可以没有抽象方法；子类未实现全部抽象方法时该类也成为抽象类；抽象方法必须是非静态的。', 1, 318, 1),
(91, 176, 'Calendar 的 MONTH 域基于 0（9 表示十月），因此 new GregorianCalendar(1949, 9, 1) 得到的是 1949 年 10 月 1 日；24 小时制用 HOUR_OF_DAY，12 小时制用 HOUR，配 AM_PM 使用，是填空题第 16 题考点。', 1, 320, 1),
(92, 183, '接口方法版本与冲突规则：Java 8 起允许 default 默认方法与公有静态方法，Java 9 起允许私有方法（只能被接口内部使用）；父类具体方法优先于接口默认方法，两个接口默认方法签名相同时编译器报错、必须由实现类重写解决，即使其中一个接口只有抽象声明也同样报错。', 2, 330, 1),
(93, 186, 'compareTo 返回值含义辨析：大于、等于、小于给定对象时分别返回正整数、零、负整数，而不是 true/false；String 的 compareTo 按字符 Unicode 值从左往右逐位相减，"Hello".compareTo("hello") 返回 -32。', 3, 336, 1),
(94, 187, '抽象类与接口的选择是本章高频考点：强「是一种」关系、一组相关类用抽象类；弱「是一种」关系、一组不相关类用接口；接口只有公有静态常量、没有构造方法，也不能用 new 创建实例，通常优先使用接口。', 2, 339, 1);
INSERT INTO `knowledge_exercise` (`id`, `chapter_id`, `question`, `answer`, `difficulty`, `knowledge_point`, `page`, `page_order`) VALUES
(479, 158, '1、 为 AB 类的一个无形式参数无返回值的方法 method 书写方法头，使得使用类名 AB 作为前缀就可以调用它，该方法头的形式为( )。\n(A) static void method( )　　(B)public void method( )\n(C)final void method( )　　(D)abstract void method( )', 'A', 1, '方法重写', 343, 1),
(480, 158, '2、 关于被保护访问控制符 protected 修饰的成员变量，以下说法正确的是（ ）\n(A)可被三种类所引用：该类自身、与它在同一个包的其他类、在其他包的该类的子类\n(B)可被两种类访问和引用：该类本身、该类的所有子类\n(C)只能被该类自身所访问和修改\n(D)只能被同一个包中的类访问', 'A', 1, 'protected 数据和方法', 343, 2),
(481, 158, '3、 以下关于继承的叙述正确的是（ ）。\n(A)在 Java 中类只允许单一继承\n(B)在 Java 中一个类只能实现一个接口\n(C)在 Java 中一个类不能同时继承一个类和实现一个接口\n(D)在 Java 中接口只允许单一继承', 'A', 1, '父类与子类', 343, 3),
(482, 158, '4、 Java 类之间的继承关系是（ ）\n(A)单继承　　(B)多继承\n(C)不能继承　　(D)不一定', 'A', 1, '父类与子类', 343, 4),
(483, 158, '5、 当你试着编译运行下面的类的时候，可能会发生什么？( )\n```java\nclass Base{\n      Base(int i){System.out.println("Base"); } }\nclass Severn extends Base{\n      public static void main(String argv[]){ Severn s = new Severn();}\n      void Severn(){ System.out.println("Severn"); } }\n```\n(A)Compilation and output of the string "Severn" at runtime\n(B)Compile time error\n(C)Compilation and no output at runtime\n(D)Compilation and output of the string "Base"', 'B', 1, '调用父类构造方法', 343, 5),
(484, 158, '6、 子类对象（ ）直接向其父类对象赋值，父类对象（ ）直接向其子类对象赋值。选择( )\n(A)能，能　　(B)能，不能\n(C)不能，能　　(D)不能，不能', 'B', 1, '对象转换', 343, 6),
(485, 158, '7、 如果局部变量和成员变量同名，在局部变量作用域内引用成员变量的方法是（ ）\n(A)不能引用，必须改名，使它们的名字不同\n(B)在成员变量前加 this\n(C)在成员变量前加 super，使用 super 访问该成员变量\n(D) 不影响，系统可以自己区分', 'B', 1, '调用父类普通方法', 343, 7),
(486, 158, '8、 给定下面的类定义\n```java\nclass Base{ Base(int i){ } }\nclass DefCon extends Base{\n      DefCon(int i){\n            //XX\n      }\n}\n```\n如果将标记//XX 的地方替换为下面的行，哪一行是独立合法的？（ ）\n(A) super();\n(B) this();\n(C) this(99);\n(D) super(99);', 'D', 1, '调用父类构造方法', 343, 8),
(487, 158, '9、 以下哪项陈述是错误的? （ ）\n(A) 始终可以将子类的实例传递给其超类类型的参数。这个特性被称为多态性\n(B) 编译器根据参数类型、参数数量和编译时参数的顺序来查找匹配方法\n(C) 一个方法可以在几个子类中实现。Java 虚拟机在运行时动态绑定方法的实现\n(D) 动态绑定可以应用于静态方法', 'D', 1, '动态绑定', 344, 9),
(488, 158, '10、给定下面的代码:\n```java\nclass C1 {}\nclass C2 extends C1 { }\nclass C3 extends C2 { }\nclass C4 extends C1 {}\nC1 c1 = new C1();\nC2 c2 = new C2();\nC3 c3 = new C3();\nC4 c4 = new C4();\n```\n下列哪个表达式的值是 false?( )。\n(A) c1 instanceof C1　　(B) c2 instanceof C1\n(C) c3 instanceof C1　　(D) c4 instanceof C2', 'D', 1, '对象转换', 344, 10),
(489, 158, '11、给定下面的类和对象:\n```java\nclass C1 {};\nclass C2 extends C1 {};\nclass C3 extends C1 {};\nC2 c2 = new C2();\nC3 c3 = new C3();\n```\n分析如下语句: c2 = (C2)((C1)c3);\n描述正确的是（ ）\n(A)c3 成功转换为 c2\n(B)你将遇到一个运行时错误，因为你不能将对象转换为兄弟对象\n(C)你将遇到一个运行时错误，因为 Java 运行时系统不能以嵌套形式执行多个类型转换\n(D)语句是正确的', 'B', 1, '对象转换', 344, 11),
(490, 158, '12、以下哪项陈述是错误的？( )。\n(A) 公有类可以被来自不同包的类访问。\n(B) 不同包中的类无法访问一个类的私有方法。\n(C) 受保护的方法可被不同包中的子类访问。\n(D) 没有可见性修饰符的方法可以被不同包中的类访问。', 'D', 1, 'protected 数据和方法', 344, 12),
(491, 158, '13、下面哪个类不能被扩展?（ ）。\n(A) class A { }　　(B) class A { private A() { } }\n(C) final class A { }　　(D) class A { protected A() { } }', 'C', 1, 'final', 344, 13),
(492, 158, '14、下列关于修饰符混用的说法，错误的是（ ）\n(A) abstract 不能与 final 并列修饰同一个类\n(B) abstract 类中不可以有 private 的成员\n(C) abstract 方法必须在 abstract 类中\n(D) static 方法中能处理非 static 的属性', 'B', 1, '抽象类', 344, 14),
(493, 158, '15、下列类定义中哪些是合法的抽象类的定义？（ ）\n(A) abstract Animal{abstract void growl();}\n(B) class abstract Animal{abstract void growl();}\n(C) abstract class Animal{abstract void growl();}\n(D) abstract class Animal{abstract void growl(){System.out.println(“growl”);}}', 'C', 1, '抽象类', 345, 15),
(494, 158, '16、下面说法不正确的是（ ）\n(A) 抽象类既可以做父类，也可以做子类\n(B) abstract 和 final 能修饰同一类\n(C) 抽象类中可以没有抽象方法，有抽象方法的类一定是抽象类\n(D) 声明为 final 类型的方法不能在其子类中重新定义', 'B', 1, '抽象类', 345, 16),
(495, 158, '17、接口的所有变量和方法分别默认为是（ ）\n(A)public final static 和 public abstract　　(B)public final static 和 public final\n(C)public static 和 public abstract　　(D)public static 和 public final', 'A', 1, '普通接口声明', 345, 17),
(496, 158, '18、下列程序片段中，能通过编译的是( )\n(A) public abstract class Animal{ public void speak(); }\n(B) public abstract class Animal{ public void speak(){ } }\n(C) public class Animal{ public abstract void speak(); }\n(D) public abstract class Animal{ public abstract void speak(){ } }', 'B', 1, '抽象类', 345, 18),
(497, 158, '19、关于抽象方法的说法正确的是( )\n(A)可以有方法体　　(B) 可以出现在非抽象类中\n(C) 是没有方法体的方法　(D) 抽象类中的方法都是抽象方法', 'C', 1, '抽象类', 345, 19),
(498, 158, '20、下列哪个类声明是正确的？( )\n(A) abstract final class HI{···｝　　(B) abstract private move(){···}\n(C) protected private number;　　(D) public abstract class Car{···}', 'D', 1, '抽象类', 345, 20),
(499, 158, '21、下面关于接口的说法中不正确的是（ ）\n(A) 接口中所有的方法都是抽象的\n(B) 接口中所有的方法都是 public 访问权限\n(C) 子接口继承父接口使用的关键字是 implements\n(D) 接口是 Java 中的特殊类，包含常量和抽象方法', 'C', 1, '父接口、子接口', 345, 21),
(500, 158, '22、为使下列代码正常运行，应该在下划线处填入的选项是( )\n```java\nabstract class Person{\n      public Person(String n){ name=n; }\n      public ________ String getDescription();\n      public String getName(){return name;}\n      private String name; }\n```\n(A) static (B) private (C) abstract (D)final', 'C', 1, '抽象类', 345, 22),
(501, 158, '23、假定 A 是一个抽象类，B 是一个具体类，B 是 A 的一个具体子类，A 和 B 均有无参构造方法，下列正确的是（ ）。\n(A) A a = new A(); (B) A a = new B();\n(C) B b = new A(); (D) B a = new A();', 'B', 1, '抽象类', 345, 23),
(502, 158, '24、下列关于抽象方法的语句中哪一个是错误的？( )\n(A) 抽象类可以使用抽象类的构造方法创建实例。\n(B) 抽象类可以被扩展\n(C) 非抽象超类的子类可以是抽象的。\n(D) 子类可以重写超类中的具体方法来声明它是抽象的。', 'A', 1, '抽象类', 346, 24),
(503, 158, '25、下列哪个是一个正确的接口?（ ）\n(A) interface A { void print() { }; }\n(B) abstract interface A { print(); }\n(C) abstract interface A { abstract void print() { };}\n(D) interface A { void print();}', 'D', 1, '普通接口声明', 346, 25),
(504, 158, '26、下面哪个说法是错误的（ ）。\n(A)当你编译一个接口文件无错误时，一个字节码文件产生。\n(B)当你编译一个抽象类文件无错误时，一个字节码文件产生。\n(C)当你编译一个类文件有错误时，一个字节码文件产生。\n(D)当你编译一个接口文件有警告错误时，一个字节码文件产生。', 'C', 1, '接口实现', 346, 26),
(505, 158, '27、关于关于注解接口体中的注解方法，说法错误的是（ ）\n(A)注解方法不能带有参数。\n(B)注解方法返回值类型限定为：基本数据类型、String、enum 类型、注解接口类型、Class、或者是这些类型的数组。\n(C)注解方法不可以有默认值。\n(D)注解本身能够包含元注解，元注解被用来注解其他注解。', 'C', 1, '注解与注解接口（Annotation Interface）', 346, 27),
